# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CUMA HUTBESİNİN ADIM ADIM UYGULAMA AKIŞ ŞEMASI</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Minbere Çıkış ve İç Ezan</text>\n  <text x="32" y="92" font-size="10.5" fill="#334155">• Cübbe ve sarıkla vakur yürüyüş.</text>\n  <text x="32" y="114" font-size="10.5" fill="#334155">• Sağ ayakla 1., 3. ve 5. basamak-</text>\n  <text x="40" y="129" font-size="10" fill="#475569">larda gizlice basamak duaları.</text>\n  <text x="32" y="152" font-size="10.5" fill="#334155">• Kıbleye dönüp kısa dua, ardından</text>\n  <text x="40" y="167" font-size="10" fill="#475569">cemaate dönüp selam ve oturuş.</text>\n  <text x="32" y="190" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Müezzinin iç ezanı okuması.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Birinci Hutbe ve Oturuş</text>\n  <text x="257" y="92" font-size="10.5" fill="#334155">• Ayağa kalkış; Hamdele, Salvele</text>\n  <text x="265" y="107" font-size="10" fill="#475569">ve Kelime-i Şehadet okunuşu.</text>\n  <text x="257" y="130" font-size="10.5" fill="#334155">• Eûzü-Besmele, konu ayeti ve</text>\n  <text x="265" y="145" font-size="10" fill="#475569">hadis-i şerifin tilaveti.</text>\n  <text x="257" y="168" font-size="10.5" fill="#334155">• Türkçe öğüt (mev\'iza) konuşması.</text>\n  <text x="257" y="190" font-size="10.5" font-weight="bold" fill="#b45309">• İki hutbe arası kısa oturuş</text>\n  <text x="265" y="205" font-size="10" font-weight="bold" fill="#b45309">(Celse / Cülûs – Sünnet).</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. İkinci Hutbe ve İniş</text>\n  <text x="482" y="92" font-size="10.5" fill="#334155">• Ayağa kalkış; ikinci hutbe</text>\n  <text x="490" y="107" font-size="10" fill="#475569">hamdele ve salvelesi.</text>\n  <text x="482" y="130" font-size="10.5" fill="#334155">• Müminler, vatan ve ümmet için</text>\n  <text x="490" y="145" font-size="10" fill="#475569">istiğfar ve Türkçe/Arapça dua.</text>\n  <text x="482" y="168" font-size="10.5" fill="#334155">• Nahl suresi 90. ayetin okunuşu.</text>\n  <text x="482" y="190" font-size="10.5" font-weight="bold" fill="#166534">• Minberden inip mihraba geçiş</text>\n  <text x="490" y="205" font-size="10" font-weight="bold" fill="#166534">ve 2 rekât Cuma farzı.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CUMA HUTBESİ İLE BAYRAM HUTBESİNİN MUKAYESESİ</text>\n  <rect x="25" y="45" width="310" height="192" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">1. Cuma Hutbesi</text>\n  <text x="40" y="94" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#0c4a6e">Fıkhî Hükmü:</tspan> Farzdır (Cumanın şartıdır).</text>\n  <text x="40" y="116" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#0c4a6e">Okunuş Vakti:</tspan> İki rekât farz namazdan ÖNCE.</text>\n  <text x="40" y="138" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#0c4a6e">Ezan ve Kamet:</tspan> İç ezan ve kamet VARDIR.</text>\n  <text x="40" y="160" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#0c4a6e">Minberde İlk Oturuş:</tspan> İç ezan okunurken oturulur.</text>\n  <rect x="42" y="176" width="276" height="46" rx="6" fill="#ffffff" stroke="#38bdf8" stroke-width="1.2"/>\n  <text x="180" y="194" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0284c7">Başlangıç Lafzı:</text>\n  <text x="180" y="211" text-anchor="middle" font-size="10" fill="#334155">Doğrudan \'Hamdele\' (Elhamdülillâh) ile başlar.</text>\n\n  <rect x="365" y="45" width="310" height="192" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">2. Bayram Hutbesi (Ramazan &amp; Kurban)</text>\n  <text x="380" y="94" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#4c1d95">Fıkhî Hükmü:</tspan> Sünnettir (Namaz vaciptir).</text>\n  <text x="380" y="116" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#4c1d95">Okunuş Vakti:</tspan> İki rekât bayram namazından SONRA.</text>\n  <text x="380" y="138" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#4c1d95">Ezan ve Kamet:</tspan> Ezan ve kamet YOKTUR.</text>\n  <text x="380" y="160" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#4c1d95">Minberde İlk Oturuş:</tspan> Oturmadan hutbeye başlanır.</text>\n  <rect x="382" y="176" width="276" height="46" rx="6" fill="#ffffff" stroke="#a855f7" stroke-width="1.2"/>\n  <text x="520" y="194" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6d28d9">Başlangıç Lafzı:</text>\n  <text x="520" y="211" text-anchor="middle" font-size="10" fill="#334155">Teşrik Tekbirleriyle (Allâhü ekber...) başlar.</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ETKİLİ HUTBE SUNUMU VE MİNBER HİTABETİ ÖLÇÜTLERİ</text>\n  <rect x="20" y="48" width="210" height="182" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">1. Ön Hazırlık ve Kıraat</text>\n  <text x="32" y="98" font-size="10.5" fill="#334155">• Hutbe metnini önceden birkaç kez</text>\n  <text x="40" y="113" font-size="10" fill="#475569">sesli okuyarak prova yapma.</text>\n  <text x="32" y="138" font-size="10.5" fill="#334155">• Ayet, hadis ve Arapça duaları</text>\n  <text x="40" y="153" font-size="10" fill="#475569">tecvit ve mahreçle doğru okuma.</text>\n  <text x="32" y="178" font-size="10.5" fill="#334155">• Temiz kıyafet, cübbe, sarık ve</text>\n  <text x="40" y="193" font-size="10" fill="#475569">güzel koku ile minbere çıkma.</text>\n\n  <rect x="245" y="48" width="210" height="182" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Ses, Vurgu ve Beden Dili</text>\n  <text x="257" y="98" font-size="10.5" fill="#334155">• Anlama uygun ses tonu, vurgu</text>\n  <text x="265" y="113" font-size="10" fill="#475569">ve akıcı diksiyon (fesahat).</text>\n  <text x="257" y="138" font-size="10.5" fill="#334155">• Sürekli metne bağlı kalmayıp</text>\n  <text x="265" y="153" font-size="10" fill="#475569">cemaatle göz teması kurma.</text>\n  <text x="257" y="178" font-size="10.5" fill="#334155">• Vakur duruş ve abartıdan uzak</text>\n  <text x="265" y="193" font-size="10" fill="#475569">doğal jest-mimik kullanımı.</text>\n\n  <rect x="470" y="48" width="210" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. Süre ve Üslup Dengesi</text>\n  <text x="482" y="98" font-size="10.5" fill="#334155">• Nebevi sünnete uygun makul</text>\n  <text x="490" y="113" font-size="10" fill="#475569">süre (cemaati bıktırmama).</text>\n  <text x="482" y="138" font-size="10.5" fill="#334155">• Nefret ettiren değil müjdeleyen</text>\n  <text x="490" y="153" font-size="10" fill="#475569">(tebşîr) ve kuşatan üslup.</text>\n  <text x="482" y="178" font-size="10.5" fill="#334155">• Toplumsal birlik ve kardeşliği</text>\n  <text x="490" y="193" font-size="10" fill="#475569">güçlendiren hikmetli mesajlar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
